import{_ as t,o,c as i,a2 as n}from"./chunks/framework.BsgK4TUM.js";const h=JSON.parse('{"title":"Donations and Invoice Payments","description":"","frontmatter":{},"headers":[],"relativePath":"how-tos/donations.md","filePath":"how-tos/donations.md"}'),a={name:"how-tos/donations.md"};function s(r,e,c,d,l,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="donations-and-invoice-payments" tabindex="-1">Donations and Invoice Payments <a class="header-anchor" href="#donations-and-invoice-payments" aria-label="Permalink to &quot;Donations and Invoice Payments&quot;">​</a></h1><p>Products can be configured to have a customer entered price - instead of a fixed price, a price entry field is displayed instead.</p><p>To configure a product this way, check the <strong>Allow customer to enter price</strong> option on the Overview tab when editing a product. When this is checked, the product&#39;s options will adjust. The following fields appear:</p><ul><li>Default Price</li><li>Price Suggestions</li><li>Minimum Price</li><li>Maximum Price</li></ul><p>Use these fields to control the limits of what can be used as a payment value. Also set the <strong>Offer quantity selection</strong> option to <strong>No, only allow one of this product in the cart</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Invoice Payments</p><p>If you are configuring a product to be used for customers to pay existing invoices online, add a <strong>Text Field</strong> option to the product, set to be required, with a label such as &#39;Invoice Number&#39;. This field can be used to associate the payment with an invoice number, and also allows multiple invoice payments to be made within the same order.</p></div>',6)])])}const m=t(a,[["render",s]]);export{h as __pageData,m as default};
